package de.backendlab.ee;
import de.backendlab.cache.*;import jakarta.annotation.*;import jakarta.enterprise.context.ApplicationScoped;import jakarta.enterprise.concurrent.ManagedScheduledExecutorService;import java.util.*;import java.util.concurrent.*;import java.sql.*;import java.time.*;
@ApplicationScoped public class Catalog {
 private final ProductCache cache=CacheFactory.create(System.getenv().getOrDefault("LAB_CACHE_STRATEGY","snapshot"));private ScheduledFuture<?> future; private boolean initialized; private Watermark mark=Watermark.empty(); private final String sync=System.getenv().getOrDefault("LAB_SYNC_STRATEGY","journal");
 @Resource(lookup="java:comp/DefaultManagedScheduledExecutorService") ManagedScheduledExecutorService timer;
 Connection connect() throws SQLException{return DriverManager.getConnection(System.getenv().getOrDefault("DB_URL","jdbc:mysql://localhost:3306/backendlab"),System.getenv().getOrDefault("DB_USER","lab"),System.getenv().getOrDefault("DB_PASSWORD","local-lab-password"));}
 @PostConstruct public void start(){if(("unsafe".equals(System.getenv("LAB_CACHE_STRATEGY"))||sync.equals("watermark"))&&!"true".equals(System.getenv("LAB_ENABLED")))throw new IllegalStateException("unsafe requires lab mode");try(var c=connect();var s=c.createStatement()){s.execute("CREATE TABLE IF NOT EXISTS products(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,last_updated_time DATETIME(6) NULL)");try(var rs=s.executeQuery("SELECT COUNT(*) FROM products")){rs.next();if(rs.getLong(1)==0)seed(c);}refresh();future=timer.scheduleWithFixedDelay(()->{try{refresh();}catch(Exception e){System.err.println(e);}},10,10,TimeUnit.SECONDS);}catch(SQLException e){throw new IllegalStateException(e);}}
 private void seed(Connection c)throws SQLException{c.setAutoCommit(false);try(var p=c.prepareStatement("INSERT INTO products(id,name) VALUES(?,?)")){for(int i=1;i<=100000;i++){p.setInt(1,i);p.setString(2,"Product "+i);p.addBatch();if(i%1000==0)p.executeBatch();}c.commit();}catch(SQLException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}
 private List<Product> rows(PreparedStatement p)throws SQLException {try(var rs=p.executeQuery()){var list=new ArrayList<Product>();while(rs.next()){var t=rs.getObject(3,LocalDateTime.class);list.add(new Product(rs.getLong(1),rs.getString(2),t==null?null:t.toInstant(ZoneOffset.UTC)));}return list;}}
 public synchronized void refresh(){try(var c=connect()){c.setTransactionIsolation(Connection.TRANSACTION_REPEATABLE_READ);c.setAutoCommit(false);try{
  if(!initialized||sync.equals("full")){try(var p=c.prepareStatement("SELECT id,name,last_updated_time FROM products")){var all=rows(p);cache.replaceAll(all);mark=Watermark.empty().advance(all);}if(sync.equals("journal")){var seen=journal(c,false);ack(c,seen.keySet());}}
  else if(sync.equals("watermark")){try(var p=c.prepareStatement("SELECT id,name,last_updated_time FROM products WHERE id>? OR last_updated_time>=?")){p.setLong(1,mark.id());p.setObject(2,LocalDateTime.ofInstant(mark.timestamp(),ZoneOffset.UTC));var changes=rows(p);cache.apply(Changes.upsert(changes));mark=mark.advance(changes);}}
  else if(sync.equals("journal")){var events=journal(c,true);var ids=new HashSet<>(events.values());var upserts=new ArrayList<Product>();var deletes=new HashSet<Long>();try(var p=c.prepareStatement("SELECT id,name,last_updated_time FROM products WHERE id=?")){for(long id:ids){p.setLong(1,id);var found=rows(p);if(found.isEmpty())deletes.add(id);else upserts.add(found.get(0));}}cache.apply(new Changes(upserts,deletes));ack(c,events.keySet());}
  else throw new IllegalArgumentException("sync strategy");c.commit();initialized=true;
 }catch(Exception e){c.rollback();throw e;}}catch(SQLException e){throw new IllegalStateException(e);}}
 private Map<Long,Long> journal(Connection c,boolean bounded)throws SQLException{var result=new LinkedHashMap<Long,Long>();try(var p=c.prepareStatement("SELECT change_id,product_id FROM product_changes ORDER BY change_id"+(bounded?" LIMIT 1000":""));var rs=p.executeQuery()){while(rs.next())result.put(rs.getLong(1),rs.getLong(2));}return result;}
 private void ack(Connection c,Collection<Long> ids)throws SQLException{try(var p=c.prepareStatement("DELETE FROM product_changes WHERE change_id=?")){int n=0;for(long id:ids){p.setLong(1,id);p.addBatch();if(++n%1000==0)p.executeBatch();}p.executeBatch();}}
 public long create(String name){try(var c=connect();var p=c.prepareStatement("INSERT INTO products(name,last_updated_time) VALUES(?,NULL)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,name);p.executeUpdate();try(var keys=p.getGeneratedKeys()){keys.next();return keys.getLong(1);}}catch(SQLException e){throw new IllegalStateException(e);}}
 public boolean rename(long id,String name){try(var c=connect();var p=c.prepareStatement("UPDATE products SET name=?,last_updated_time=UTC_TIMESTAMP(6) WHERE id=?")){p.setString(1,name);p.setLong(2,id);return p.executeUpdate()>0;}catch(SQLException e){throw new IllegalStateException(e);}}
 public boolean delete(long id){try(var c=connect();var p=c.prepareStatement("DELETE FROM products WHERE id=?")){p.setLong(1,id);return p.executeUpdate()>0;}catch(SQLException e){throw new IllegalStateException(e);}}
 public ProductPage page(int page,int size,String search){return cache.page(page,size,search);}public Product get(long id){return cache.get(id).orElseThrow(jakarta.ws.rs.NotFoundException::new);}public int size(){return cache.size();}public String sync(){return sync;}
 @PreDestroy public void close(){if(future!=null)future.cancel(false);}
}
